{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Zongertinib, a covalent HER2 inhibitor containing an acrylamide warhead and a heteroaromatic aniline core similar to the query, has a predicted human oral bioavailability of 41%, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Imatinib, an anilino-pyrimidine kinase inhibitor with a basic amine side chain, has an absolute oral bioavailability of 98.3% in healthy subjects, demonstrating that this scaffold class can achieve high F despite substantial size and polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "The brigatinib/GSK1322322 scaffold, which shares the methoxy-aniline pyrimidine and basic amine features with the query, achieved 77% absolute oral bioavailability in fed healthy volunteers, with fasted values also well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Golidocitinib, a JAK inhibitor with an anilino-pyrimidine and piperazine motif, showed >80% oral bioavailability in a human radiolabeled mass balance study.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Brexpiprazole, which contains an N-methyl indazole moiety like the query, has 95% oral bioavailability in humans, supporting high F for this heteroaromatic substructure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Encorafenib, a pyrimidine-based kinase inhibitor with a complex polar side chain, has 85% human oral bioavailability, reinforcing that complex heteroaromatic drugs can be well absorbed.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite an unfavorable physicochemical prior, the preponderance of transferable human quantitative bioavailability data from structurally related kinase inhibitors—including acrylamide-containing zongertinib (41%), anilino-pyrimidines (46-98%), and N-methyl indazole-containing brexpiprazole (95%)—supports F >= 20%. No experimental evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "The stability of the isopropyl ester and the acrylamide warhead toward first-pass metabolism is not directly addressed by the analogues.",
    "The impact of very low neutral fraction and high TPSA on human absorption is uncertain, though related compounds still achieved high F.",
    "Food effects and solubility-limited absorption at therapeutic doses are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

